mapper.select:
select er.*, pr.`name` paper_name , pr. total_score paper_total_score, TIMESTAMPDIFF(MINUTE, er.start_time, er.end_time) duration from exam_records er left join paper pr on er.exam_id = pr.id where er.is_deleted = 0 and pr.is_deleted = 0 and er.`status` = '已批阅'
and pr.class_course_id=#{ccId}
and pr.id=#{paperId}
order by er.score desc , duration asc
limit #{limit};

select count(id) from exam_records


        and status = '已批阅'


        and create_time > #{begin}


        and create_time < #{end}
